<template>
  <section class="min-h-screen bg-base-200 px-4 py-6 sm:px-6 lg:px-8">
    <div class="mx-auto max-w-[1500px] space-y-5">
      <header class="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between">
        <div><p class="text-[.68rem] font-black uppercase tracking-[.16em] text-red-600">Dispatch</p><h1 class="mt-1 text-3xl font-black tracking-tight text-slate-950 dark:text-white">Resource Assignment</h1><p class="mt-2 max-w-3xl text-sm text-slate-500 dark:text-white/45">Turn an accepted incident into a real rescue mission by locking one dispatch-ready ambulance and an available response crew.</p></div>
        <button class="inline-flex items-center justify-center gap-2 rounded-xl border border-base-300 bg-base-100 px-4 py-2.5 text-sm font-bold text-slate-700 shadow-sm hover:bg-base-200 dark:border-white/10 dark:bg-[#0d2943] dark:text-white/65" @click="load"><Icon icon="lucide:refresh-cw" width="16" :class="loading?'animate-spin':''"/>Refresh</button>
